import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { PaymentService } from './payment.service';

@Component({
  selector: 'app-payment-methods',
  templateUrl: './payment-methods.component.html',
  styleUrls: ['./payment-methods.component.css'],
})
export class PaymentMethodsComponent implements OnInit {
  paymentMethods: any[] = [];
  showForm = false;
  showModal = false; // Controla a visibilidade do modal
  paymentMethodForm: FormGroup;

  constructor(private service: PaymentService, private fb: FormBuilder) {
    this.paymentMethodForm = this.fb.group({
      method: ['', [Validators.required, Validators.maxLength(50)]],
      description: ['', Validators.maxLength(200)],
    });
  }

  ngOnInit(): void {
    this.getPaymentMethods();
  }

  getPaymentMethods(): void {
    this.service.findAll().subscribe((res: any) => {
      this.paymentMethods = res.result;
      console.log('paymentMethods', this.paymentMethods);
    });
  }

  toggleForm(): void {
    this.showForm = !this.showForm;
    if (!this.showForm) this.paymentMethodForm.reset(); // Limpa o formulário se o mesmo for fechado
  }

  addPaymentMethod(): void {
    if (this.paymentMethodForm.valid) {
      this.toggleModal(); // Exibe o modal de confirmação
    }
  }

  handleConfirm(): void {
    // Salva o método de pagamento após confirmação
    console.log(this.paymentMethodForm.value);
    this.service.create(this.paymentMethodForm.value).subscribe(() => {
      this.getPaymentMethods(); // Atualiza a lista de métodos de pagamento
      this.toggleForm(); // Fecha o formulário
      this.toggleModal(); // Fecha o modal
    });
  }

  handleCancel(): void {
    console.log('Ação cancelada!');
    this.toggleModal(); // Fecha o modal sem salvar
  }

  toggleModal(): void {
    this.showModal = !this.showModal;
  }

  deletePaymentMethod(id: number): void {
    this.service.delete(id.toString()).subscribe(() => {
      this.getPaymentMethods(); 
    });
  }
}
<app-page-body>
  <h2>Métodos de Pagamento</h2>

  <button (click)="toggleForm()" class="btn-new-method">Novo</button>

  <div *ngIf="showForm" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="toggleForm()">&times;</span>
      <h2>Cadastrar Método de Pagamento</h2>
      <form [formGroup]="paymentMethodForm" (ngSubmit)="addPaymentMethod()">
        <label for="name">Nome:</label>
        <input id="name" formControlName="method" required />

        <button type="submit" [disabled]="paymentMethodForm.invalid">
          Cadastrar
        </button>
      </form>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Id</th>
        <th>Nome</th>
        <th>Ações</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let method of paymentMethods">
        <td>{{ method.id }}</td>
        <td>{{ method.method }}</td>

        <td>
          <button
            class="btn-icon delete-btn"
            (click)="deletePaymentMethod(method.id)"
          >
            <i class="fa fa-trash"></i>
          </button>
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="paymentMethods.length === 0">
    Nenhum método de pagamento cadastrado.
  </p>
  <app-modal
    [visible]="showModal"
    title="Confirmação"
    message="Deseja realmente salvar este registro?"
    (onConfirm)="handleConfirm()"
    (onCancel)="handleCancel()"
  ></app-modal>
</app-page-body>
